define([],function(){return{init:function(){var dropZone=document.getElementById("file-drop-zone"),fileInput=document.getElementById("spreadsheet"),fileName=document.getElementById("file-name"),fileNameText=document.getElementById("file-name-text");if(!dropZone||!fileInput)return;function preventDefaults(e){e.preventDefault();e.stopPropagation()}function displayFileName(file){if(file){fileNameText.textContent=file.name;fileName.style.display="block";dropZone.classList.add("has-file")}}["dragenter","dragover","dragleave","drop"].forEach(function(eventName){dropZone.addEventListener(eventName,preventDefaults,!1);document.body.addEventListener(eventName,preventDefaults,!1)});["dragenter","dragover"].forEach(function(eventName){dropZone.addEventListener(eventName,function(){dropZone.classList.add("drag-over")},!1)});["dragleave","drop"].forEach(function(eventName){dropZone.addEventListener(eventName,function(){dropZone.classList.remove("drag-over")},!1)});dropZone.addEventListener("drop",function(e){var dt=e.dataTransfer;var files=dt.files;if(files.length>0){fileInput.files=files;displayFileName(files[0])}},!1);fileInput.addEventListener("change",function(){if(fileInput.files.length>0){displayFileName(fileInput.files[0])}});var formatSelect=document.getElementById("format");if(formatSelect){formatSelect.addEventListener("change",function(){var selectedOption=this.options[this.selectedIndex];var description=selectedOption.getAttribute("data-description");var descriptionElement=document.getElementById("format-description");if(descriptionElement){descriptionElement.textContent=description||""}})}}}})
